H.background();
// Doppler effect:  f_obs = f_src * v / (v -/+ v_src)   (v = 340 m/s sound speed).
// The source travels back and forth; each wavefront is a circle centered on
// the source's PAST position, expanding at the sound speed. Because the source
// chases its own forward wavefronts, the rings bunch AHEAD (higher pitch) and
// stretch BEHIND (lower pitch). Source draw-speed scales with the v_src slider,
// so the Mach ratio (drawSpeed/cDraw) equals the real ratio v_src/v.
const fsrc = Math.max(1, P.f);          // emitted frequency (Hz)
const vsrc = Math.max(0, P.vs);         // source speed (m/s)
const c = 340;                          // speed of sound (m/s)
const v = H.plot2d({ xMin: -200, xMax: 200, yMin: -110, yMax: 110 });
v.grid({ stepX: 100, stepY: 50 }); v.axes({ stepX: 100, stepY: 50 });
// --- drawing scales: ring radius grows at cDraw units/s; source moves at the
// SAME fraction of cDraw that vsrc is of c, so the picture is to scale. ---
const cDraw = 70;                       // drawing units / sec for the wavefronts
const vDraw = (vsrc / c) * cDraw;       // source speed in drawing units (subsonic for vsrc<c)
const half = 180;                       // source turns around at +/- half
// triangle-wave position so the source sweeps back and forth at constant speed vDraw
function srcPos(time){
  if (vDraw <= 1e-6) return 0;
  const span = 4 * half / vDraw;        // period of the back-and-forth sweep
  let u = ((time % span) + span) % span;
  const seg = vDraw * u;
  if (seg <= 2 * half) return -half + seg;          // moving right
  return 3 * half - seg;                            // moving left
}
function srcVel(time){
  const dt = 0.01;
  return (srcPos(time + dt) - srcPos(time - dt)) / (2 * dt);
}
const sx = srcPos(t);
const sv = srcVel(t);                   // signed drawn velocity (units/s)
// emit a ring every Temit seconds from where the source actually was then
const Temit = 0.4;
for (let n = 1; n <= 8; n++) {
  const age = n * Temit;
  const cxEmit = srcPos(t - age);       // source position at emission
  const rad = cDraw * age;              // wavefront radius now
  if (rad > 260) continue;              // off-field, skip
  const ring = [];
  for (let i = 0; i <= 48; i++) {
    const th = i / 48 * H.TAU;
    ring.push([cxEmit + rad * Math.cos(th), rad * Math.sin(th)]);
  }
  v.path(ring, { color: H.colors.accent, width: 1.5 });
}
// the source + a velocity arrow
v.dot(sx, 0, { r: 7, fill: H.colors.warn });
v.arrow(sx, 0, sx + Math.sign(sv) * 40, 0, { color: H.colors.warn, width: 2 });
// observed frequencies: ahead (toward) raises pitch, behind (away) lowers it
const denom = Math.max(1, c - vsrc);
const fAhead = fsrc * c / denom;        // listener the source moves toward
const fBehind = fsrc * c / (c + vsrc);  // listener the source moves away from
const movingRight = sv >= 0;
v.text(movingRight ? "ahead (compressed)" : "behind (stretched)", sx + (movingRight ? 30 : -150), 80, { color: H.colors.good, size: 12 });
H.text("Doppler effect:  f' = f · v / (v ∓ v_src)", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("f = " + fsrc.toFixed(0) + " Hz   v_src = " + vsrc.toFixed(0) + " m/s   ahead: " + fAhead.toFixed(0) + " Hz (higher)   behind: " + fBehind.toFixed(0) + " Hz (lower)", 24, 52, { color: H.colors.sub, size: 12 });
H.legend([{ label: "wavefronts", color: H.colors.accent }, { label: "source", color: H.colors.warn }], H.W - 170, 28);
